// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.RepositoryResult;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.api.parallel.ResourceLock;
import org.junit.jupiter.api.parallel.Resources;

/**
 * Reads that turn a value into its stored ID (the subject of {@code getStatements}, a SPARQL constant) are answered by
 * the value overlay's reverse index once the overlay is ready, instead of reading the LMDB dictionary.
 */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbSnapshotIdOverlayTest {

	private static final String BUDGET_PROPERTY = "rdf4j.lmdb.valueOverlay.maxBytes";
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final String NS = "urn:snapshot-id-overlay:";
	private static final IRI KNOWS = VF.createIRI(NS, "knows");

	@TempDir
	File directory;

	private String previousBudget;
	private SailRepository repository;
	private LmdbStore store;

	@BeforeEach
	void setUp() {
		previousBudget = System.getProperty(BUDGET_PROPERTY);
		System.setProperty(BUDGET_PROPERTY, "33554432");
		open();
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			for (int i = 0; i < 100; i++) {
				connection.add(node(i), KNOWS, node((i + 1) % 100));
			}
			connection.commit();
		}
		// Reopen so that the startup warm-up captures every value written above.
		repository.shutDown();
		open();
	}

	@AfterEach
	void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
		if (previousBudget == null) {
			System.clearProperty(BUDGET_PROPERTY);
		} else {
			System.setProperty(BUDGET_PROPERTY, previousBudget);
		}
	}

	@Test
	@Timeout(60)
	void getStatementsResolvesItsSubjectThroughTheOverlay() {
		ValueStore values = store.getBackingStore().valueStore();
		ValueStore.SnapshotIdLookups before = values.snapshotIdLookups();
		long rows;
		try (RepositoryConnection connection = repository.getConnection();
				RepositoryResult<?> statements = connection.getStatements(node(42), null, null, true)) {
			rows = statements.stream().count();
		}
		ValueStore.SnapshotIdLookups after = values.snapshotIdLookups();

		assertThat(rows).isEqualTo(1);
		assertThat(after.dictionaryReads()).as("no dictionary read for a value the overlay holds")
				.isEqualTo(before.dictionaryReads());
		assertThat(after.overlayHits()).isGreaterThan(before.overlayHits());
	}

	@Test
	@Timeout(60)
	void sparqlConstantsResolveThroughTheOverlay() {
		ValueStore values = store.getBackingStore().valueStore();
		ValueStore.SnapshotIdLookups before = values.snapshotIdLookups();
		long rows = 0;
		try (RepositoryConnection connection = repository.getConnection();
				TupleQueryResult result = connection
						.prepareTupleQuery("SELECT ?o WHERE { <" + NS + "n7> <" + KNOWS + "> ?o }")
						.evaluate()) {
			while (result.hasNext()) {
				assertThat(result.next().getValue("o")).isEqualTo(node(8));
				rows++;
			}
		}
		ValueStore.SnapshotIdLookups after = values.snapshotIdLookups();

		assertThat(rows).isEqualTo(1);
		assertThat(after.dictionaryReads()).isEqualTo(before.dictionaryReads());
		assertThat(after.overlayHits()).isGreaterThan(before.overlayHits());
	}

	@Test
	@Timeout(60)
	void anUnknownValueStillFallsBackToTheDictionary() {
		ValueStore values = store.getBackingStore().valueStore();
		ValueStore.SnapshotIdLookups before = values.snapshotIdLookups();
		try (RepositoryConnection connection = repository.getConnection()) {
			assertThat(connection.hasStatement(VF.createIRI(NS, "missing"), null, null, true)).isFalse();
		}
		assertThat(values.snapshotIdLookups().dictionaryReads()).isGreaterThan(before.dictionaryReads());
	}

	private void open() {
		store = new LmdbStore(directory, new LmdbStoreConfig("spoc,posc").setValueOverlayEnabled(true));
		repository = new SailRepository(store);
		repository.init();
		try {
			assertThat(store.awaitValueOverlayReady(30, TimeUnit.SECONDS)).as("value overlay ready").isTrue();
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new AssertionError(e);
		}
	}

	private static IRI node(int i) {
		return VF.createIRI(NS, "n" + i);
	}
}
